insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-pharmaceutics-extra-mcq-01','Pharmacy','Diploma in Pharmacy','mcq','free',1601,'{"question":"Which branch of pharmacy deals with the formulation and preparation of medicines?","translation":"औषधिको formulation र तयारीसँग सम्बन्धित शाखा कुन हो?","options":["Pharmaceutics","Pharmacognosy","Toxicology","Pharmacovigilance"],"correctIndex":0,"explanation":"Pharmaceutics applies scientific principles to convert drug substances into suitable dosage forms.","explanationNe":"Pharmaceutics ले औषधीय पदार्थलाई उपयुक्त dosage form मा तयार गर्न वैज्ञानिक सिद्धान्त प्रयोग गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-02','Pharmacy','Diploma in Pharmacy','mcq','free',1602,'{"question":"A dosage form is selected mainly to:","translation":"Dosage form मुख्यतः किन छनोट गरिन्छ?","options":["Ensure convenient and appropriate drug delivery","Change the drug''s identity","Increase package weight","Avoid quality control"],"correctIndex":0,"explanation":"Dosage forms support accurate dosing, stability, acceptability and delivery to the intended site.","explanationNe":"Dosage form ले सही मात्रा, स्थिरता, स्वीकार्यता र लक्षित स्थानमा औषधि पुर्‍याउन मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-03','Pharmacy','Diploma in Pharmacy','mcq','free',1603,'{"question":"Which is a solid dosage form?","translation":"ठोस dosage form कुन हो?","options":["Tablet","Syrup","Injection","Emulsion"],"correctIndex":0,"explanation":"Tablets are solid preparations containing drug with suitable excipients.","explanationNe":"Tablet औषधि र उपयुक्त excipients बाट बनेको ठोस तयारी हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-04','Pharmacy','Diploma in Pharmacy','mcq','free',1604,'{"question":"A syrup is generally a:","translation":"Syrup सामान्यतया कस्तो तयारी हो?","options":["Concentrated aqueous sugar solution","Dry powder only","Oil-in-water emulsion","Sterile gas"],"correctIndex":0,"explanation":"Syrups are concentrated aqueous preparations containing sugar or suitable sweeteners.","explanationNe":"Syrup चिनी वा उपयुक्त मिठास दिने पदार्थ भएको सघन जलीय तयारी हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-05','Pharmacy','Diploma in Pharmacy','mcq','free',1605,'{"question":"An elixir is usually:","translation":"Elixir सामान्यतया के हो?","options":["A clear, sweetened hydroalcoholic oral liquid","A sterile suspension for injection","A compressed powder","A topical ointment"],"correctIndex":0,"explanation":"Elixirs are clear, sweetened hydroalcoholic liquids for oral use.","explanationNe":"Elixir मुखबाट सेवन गरिने सफा, मिठासयुक्त पानी-अल्कोहल मिश्रित तरल हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-06','Pharmacy','Diploma in Pharmacy','mcq','free',1606,'{"question":"A suspension contains:","translation":"Suspension मा के हुन्छ?","options":["Insoluble solid particles dispersed in a liquid","Only dissolved molecules","Two completely miscible liquids","Gas dissolved in solid"],"correctIndex":0,"explanation":"Suspensions contain finely divided insoluble particles dispersed in a continuous liquid phase.","explanationNe":"Suspension मा नघुल्ने साना ठोस कण तरल माध्यममा फैलिएका हुन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-07','Pharmacy','Diploma in Pharmacy','mcq','free',1607,'{"question":"A label instruction for many oral suspensions is:","translation":"धेरै oral suspension मा कुन निर्देशन उपयुक्त हुन्छ?","options":["Shake well before use","Freeze before every dose","Use only by injection","Do not measure the dose"],"correctIndex":0,"explanation":"Shaking redistributes settled particles to help deliver a more uniform dose.","explanationNe":"हल्लाउँदा तल बसेका कण फेरि फैलिन्छन् र तुलनात्मक रूपमा समान मात्रा प्राप्त हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-08','Pharmacy','Diploma in Pharmacy','mcq','free',1608,'{"question":"An emulsion is a dispersion of:","translation":"Emulsion केको dispersion हो?","options":["One immiscible liquid in another","Solid in gas only","Gas in solid only","Two dissolved salts"],"correctIndex":0,"explanation":"An emulsion contains droplets of one liquid dispersed in another immiscible liquid.","explanationNe":"Emulsion मा नमिसिने एउटा तरलका थोपा अर्को तरलमा फैलिएका हुन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-09','Pharmacy','Diploma in Pharmacy','mcq','free',1609,'{"question":"An emulsifying agent helps to:","translation":"Emulsifying agent ले के गर्छ?","options":["Stabilize the interface between two liquid phases","Sterilize every preparation","Increase tablet hardness","Measure pH"],"correctIndex":0,"explanation":"Emulsifiers reduce interfacial tension and help prevent droplet coalescence.","explanationNe":"Emulsifier ले दुई तरलबीचको interfacial tension घटाएर थोपा मिसिएर छुट्टिन नदिन मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-10','Pharmacy','Diploma in Pharmacy','mcq','free',1610,'{"question":"An ointment is generally intended for:","translation":"Ointment सामान्यतया केका लागि प्रयोग हुन्छ?","options":["Application to skin or mucous membranes","Oral injection","Inhalation as a gas","Intravenous infusion"],"correctIndex":0,"explanation":"Ointments are semisolid preparations applied externally or to suitable mucosal surfaces.","explanationNe":"Ointment छाला वा उपयुक्त श्लेष्म झिल्लीमा लगाइने अर्धठोस तयारी हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-11','Pharmacy','Diploma in Pharmacy','mcq','free',1611,'{"question":"A cream is generally a:","translation":"Cream सामान्यतया कस्तो तयारी हो?","options":["Semisolid emulsion","Compressed solid","Sterile gas","Simple aqueous solution only"],"correctIndex":0,"explanation":"Creams are semisolid emulsion preparations for topical application.","explanationNe":"Cream छालामा लगाइने अर्धठोस emulsion तयारी हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-12','Pharmacy','Diploma in Pharmacy','mcq','free',1612,'{"question":"A suppository is designed to be inserted into the:","translation":"Suppository कहाँ राख्न बनाइन्छ?","options":["Rectum or another body cavity as appropriate","Bloodstream directly","Stomach through a feeding tube only","Outer surface of a tablet"],"correctIndex":0,"explanation":"Suppositories are solid dosage forms that soften, melt or dissolve after insertion.","explanationNe":"Suppository शरीरको उपयुक्त cavity मा राखेपछि नरम हुने, पग्लिने वा घुल्ने ठोस dosage form हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-13','Pharmacy','Diploma in Pharmacy','mcq','free',1613,'{"question":"Which route commonly requires sterile preparations?","translation":"कुन मार्गमा सामान्यतया sterile तयारी आवश्यक हुन्छ?","options":["Parenteral route","Oral route","Topical route in all cases","Rectal route in all cases"],"correctIndex":0,"explanation":"Preparations administered by injection must meet applicable sterility and quality requirements.","explanationNe":"Injection बाट दिइने तयारीले लागू sterility र गुणस्तर मापदण्ड पूरा गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-14','Pharmacy','Diploma in Pharmacy','mcq','free',1614,'{"question":"A pharmacopoeia is an official publication containing:","translation":"Pharmacopoeia मा के हुन्छ?","options":["Standards for medicines and pharmaceutical substances","Only medicine advertisements","Patient appointment lists","Retail shop accounts"],"correctIndex":0,"explanation":"Pharmacopoeias provide official quality standards and test methods for specified substances and preparations.","explanationNe":"Pharmacopoeia ले औषधि तथा तयारीका आधिकारिक गुणस्तर मापदण्ड र परीक्षण विधि दिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-15','Pharmacy','Diploma in Pharmacy','mcq','free',1615,'{"question":"A formulary generally provides:","translation":"Formulary ले सामान्यतया के दिन्छ?","options":["Information about selected medicines and their use","Only chemical structures","Only equipment prices","A list of expired products"],"correctIndex":0,"explanation":"A formulary summarizes approved or selected medicines and practical prescribing information.","explanationNe":"Formulary ले छनोट वा स्वीकृत औषधि र तिनको प्रयोगसम्बन्धी व्यावहारिक जानकारी दिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-16','Pharmacy','Diploma in Pharmacy','mcq','free',1616,'{"question":"An excipient is:","translation":"Excipient भनेको के हो?","options":["An inactive ingredient used in a formulation","Always the active drug","A disease-causing organism","A prescription error"],"correctIndex":0,"explanation":"Excipients support manufacture, stability, appearance, taste or performance of a dosage form.","explanationNe":"Excipient ले औषधि निर्माण, स्थिरता, रूप, स्वाद वा कार्यसम्पादनमा सहयोग गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-17','Pharmacy','Diploma in Pharmacy','mcq','free',1617,'{"question":"A diluent in a tablet formulation is used mainly to:","translation":"Tablet मा diluent किन प्रयोग गरिन्छ?","options":["Add bulk when the drug dose is small","Provide sterility","Act as a preservative in every case","Colour the package"],"correctIndex":0,"explanation":"Diluents increase tablet bulk to enable accurate manufacturing and handling.","explanationNe":"औषधिको मात्रा कम हुँदा tablet को आकार र निर्माण सहज बनाउन diluent थपिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-18','Pharmacy','Diploma in Pharmacy','mcq','free',1618,'{"question":"A binder in tablet manufacture helps to:","translation":"Tablet निर्माणमा binder ले के गर्छ?","options":["Hold powder particles together","Prevent all dissolution","Sterilize the tablet","Measure tablet weight"],"correctIndex":0,"explanation":"Binders provide cohesion to granules or powder during tablet formation.","explanationNe":"Binder ले tablet बनाउँदा कणहरूलाई एकसाथ बाँध्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-19','Pharmacy','Diploma in Pharmacy','mcq','free',1619,'{"question":"A disintegrant helps a tablet to:","translation":"Disintegrant ले tablet लाई के गर्न मद्दत गर्छ?","options":["Break up after administration","Remain intact forever","Become sterile","Change into an ointment"],"correctIndex":0,"explanation":"Disintegrants promote tablet breakup into smaller particles in the gastrointestinal fluid.","explanationNe":"Disintegrant ले पाचननलीको तरलमा tablet टुक्रिन मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-20','Pharmacy','Diploma in Pharmacy','mcq','free',1620,'{"question":"A lubricant is added during tablet manufacture to:","translation":"Tablet निर्माणमा lubricant किन थपिन्छ?","options":["Reduce friction during compression and ejection","Increase microbial growth","Add sweetness only","Cause immediate disintegration"],"correctIndex":0,"explanation":"Lubricants reduce friction between the tablet and machine surfaces.","explanationNe":"Lubricant ले tablet र मेसिनको सतहबीचको घर्षण घटाउँछ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-21','Pharmacy','Diploma in Pharmacy','mcq','free',1621,'{"question":"Granulation is commonly performed to improve:","translation":"Granulation सामान्यतया के सुधार्न गरिन्छ?","options":["Flow and compressibility of powders","Colour of the pharmacy","Sterility of all drugs","Drug price"],"correctIndex":0,"explanation":"Granulation can improve powder flow, content uniformity and compression properties.","explanationNe":"Granulation ले powder को flow, content uniformity र compression गुण सुधार्न सक्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-22','Pharmacy','Diploma in Pharmacy','mcq','free',1622,'{"question":"The main purpose of tablet coating may include:","translation":"Tablet coating को मुख्य उद्देश्यमा के पर्छ?","options":["Taste masking and protection","Replacing the active ingredient","Measuring blood pressure","Guaranteeing zero side effects"],"correctIndex":0,"explanation":"Coating may protect the drug, mask taste, improve appearance or modify release.","explanationNe":"Coating ले औषधि जोगाउन, स्वाद छोप्न, रूप सुधार्न वा release परिवर्तन गर्न सक्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-23','Pharmacy','Diploma in Pharmacy','mcq','free',1623,'{"question":"Enteric coating is designed to:","translation":"Enteric coating किन बनाइन्छ?","options":["Resist dissolution in the stomach and dissolve in intestinal conditions","Dissolve only in the mouth","Make a tablet injectable","Prevent absorption permanently"],"correctIndex":0,"explanation":"Enteric polymers resist gastric conditions and dissolve at a higher intestinal pH.","explanationNe":"Enteric coating पेटको अम्लीय अवस्थामा नघुली आन्द्राको उपयुक्त pH मा घुल्ने गरी बनाइन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-24','Pharmacy','Diploma in Pharmacy','mcq','free',1624,'{"question":"Bioavailability refers to the:","translation":"Bioavailability भन्नाले के बुझिन्छ?","options":["Rate and extent of active drug reaching systemic circulation","Colour of the medicine","Amount of excipient in a tablet","Shelf size"],"correctIndex":0,"explanation":"Bioavailability describes the rate and extent to which active drug becomes available at the systemic circulation.","explanationNe":"औषधिको सक्रिय अंश systemic circulation मा पुग्ने गति र परिमाणलाई bioavailability भनिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-25','Pharmacy','Diploma in Pharmacy','mcq','free',1625,'{"question":"A solution is a:","translation":"Solution भनेको के हो?","options":["Homogeneous mixture of solute and solvent","Mixture with visible large particles","Two separate liquid layers","Dry powder blend only"],"correctIndex":0,"explanation":"A solution is homogeneous at the molecular or ionic level.","explanationNe":"Solution मा solute र solvent समान रूपमा मिसिएका हुन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-26','Pharmacy','Diploma in Pharmacy','mcq','free',1626,'{"question":"In a percentage w/v solution, the percentage means:","translation":"प्रतिशत w/v solution मा प्रतिशतले के जनाउँछ?","options":["Grams of solute per 100 mL of solution","mL of solute per 100 g of solution","Grams per 100 g of solvent","Moles per litre only"],"correctIndex":0,"explanation":"% w/v expresses grams of solute in each 100 mL of final solution.","explanationNe":"% w/v ले अन्तिम solution को प्रत्येक १०० mL मा solute का ग्राम जनाउँछ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-27','Pharmacy','Diploma in Pharmacy','mcq','free',1627,'{"question":"A 1% w/v solution contains:","translation":"१% w/v solution मा कति solute हुन्छ?","options":["1 g in 100 mL final solution","1 g in 1 mL","10 g in 100 mL","1 mg in 100 mL"],"correctIndex":0,"explanation":"One percent weight/volume is one gram made up to 100 mL of solution.","explanationNe":"१% w/v भनेको १ ग्राम solute राखी अन्तिम solution १०० mL बनाउनु हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-28','Pharmacy','Diploma in Pharmacy','mcq','free',1628,'{"question":"The usual formula for dilution is:","translation":"Dilution को सामान्य सूत्र कुन हो?","options":["C1V1 = C2V2","P = IV","F = ma","E = mc²"],"correctIndex":0,"explanation":"For simple dilution with conserved solute amount, initial concentration times volume equals final concentration times volume.","explanationNe":"साधारण dilution मा solute को मात्रा उही रहने भएकाले C1V1 = C2V2 प्रयोग हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-29','Pharmacy','Diploma in Pharmacy','mcq','free',1629,'{"question":"If 10 mL of a 10% solution is diluted to 100 mL, the final concentration is:","translation":"१०% solution को १० mL लाई १०० mL सम्म dilute गर्दा अन्तिम concentration कति हुन्छ?","options":["1%","10%","100%","0.1%"],"correctIndex":0,"explanation":"C2 = (10% × 10 mL) / 100 mL = 1%.","explanationNe":"C2 = (१०% × १० mL) / १०० mL = १% हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-30','Pharmacy','Diploma in Pharmacy','mcq','free',1630,'{"question":"The SI unit of mass is:","translation":"Mass को SI unit कुन हो?","options":["Kilogram","Litre","Metre","Second"],"correctIndex":0,"explanation":"The kilogram is the SI base unit of mass.","explanationNe":"Kilogram mass को SI आधारभूत एकाइ हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-31','Pharmacy','Diploma in Pharmacy','mcq','free',1631,'{"question":"The basic SI unit of volume is:","translation":"आयतनको SI आधारभूत एकाइ कुन हो?","options":["Cubic metre","Kilogram","Second","Kelvin"],"correctIndex":0,"explanation":"The SI derived unit of volume is the cubic metre; litres are commonly used in pharmacy.","explanationNe":"आयतनको SI derived unit cubic metre हो; फार्मेसीमा litre पनि सामान्य प्रयोग हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-32','Pharmacy','Diploma in Pharmacy','mcq','free',1632,'{"question":"A balance should be checked for accuracy using:","translation":"Balance को accuracy कसरी जाँचिन्छ?","options":["Suitable calibrated weights","A random tablet","Water temperature","A measuring cylinder"],"correctIndex":0,"explanation":"Appropriate calibrated weights are used to check balance performance.","explanationNe":"Balance को कार्यक्षमता उपयुक्त calibrated weights प्रयोग गरेर जाँचिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-33','Pharmacy','Diploma in Pharmacy','mcq','free',1633,'{"question":"A measuring cylinder is primarily used to measure:","translation":"Measuring cylinder मुख्यतः के नाप्न प्रयोग हुन्छ?","options":["Liquid volume","Mass of powder","Tablet hardness","Temperature"],"correctIndex":0,"explanation":"A measuring cylinder measures liquid volume, with appropriate precision for the task.","explanationNe":"Measuring cylinder ले आवश्यक precision अनुसार तरलको आयतन नाप्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-34','Pharmacy','Diploma in Pharmacy','mcq','free',1634,'{"question":"The meniscus should generally be read:","translation":"Meniscus सामान्यतया कसरी पढ्नुपर्छ?","options":["At eye level","From above the cylinder","From below the bench","With the cylinder tilted"],"correctIndex":0,"explanation":"Reading at eye level reduces parallax error; for many aqueous liquids read the lower meniscus.","explanationNe":"आँखाको तहमा पढ्दा parallax error घट्छ; धेरै जलीय तरलमा तल्लो meniscus पढिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-35','Pharmacy','Diploma in Pharmacy','mcq','free',1635,'{"question":"A preservative in a multi-dose liquid preparation helps to:","translation":"Multi-dose liquid तयारीमा preservative ले के गर्छ?","options":["Inhibit microbial growth during use","Replace proper storage","Guarantee sterility after opening","Increase active drug dose"],"correctIndex":0,"explanation":"Preservatives limit microbial growth but do not replace good manufacturing, handling or storage.","explanationNe":"Preservative ले सूक्ष्मजीवको वृद्धि सीमित गर्छ तर राम्रो निर्माण, प्रयोग र भण्डारणको विकल्प होइन।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-36','Pharmacy','Diploma in Pharmacy','mcq','free',1636,'{"question":"A buffer solution resists changes in:","translation":"Buffer solution ले केमा परिवर्तन हुन दिँदैन?","options":["pH","Mass","Volume in every case","Colour only"],"correctIndex":0,"explanation":"Buffers resist pH changes when small amounts of acid or base are added.","explanationNe":"थोरै acid वा base थप्दा buffer ले pH परिवर्तन कम गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-37','Pharmacy','Diploma in Pharmacy','mcq','free',1637,'{"question":"The pH of a neutral aqueous solution at about 25°C is approximately:","translation":"करिब २५°C मा neutral जलीय solution को pH कति हुन्छ?","options":["7","1","4","14"],"correctIndex":0,"explanation":"At about 25°C, neutral water has pH close to 7.","explanationNe":"करिब २५°C मा neutral पानीको pH लगभग ७ हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-38','Pharmacy','Diploma in Pharmacy','mcq','free',1638,'{"question":"A suspension should be evaluated for:","translation":"Suspension को मूल्याङ्कन गर्दा के जाँचिन्छ?","options":["Sedimentation, redispersibility and dose uniformity","Tablet friability only","Capsule shell colour only","Electrical conductivity only"],"correctIndex":0,"explanation":"These tests help assess physical stability and consistent dosing.","explanationNe":"यी परीक्षणले भौतिक स्थिरता र समान मात्रा सुनिश्चित गर्न मद्दत गर्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-39','Pharmacy','Diploma in Pharmacy','mcq','free',1639,'{"question":"Stability of a pharmaceutical product means its ability to:","translation":"औषधिको stability भन्नाले के बुझिन्छ?","options":["Maintain specified quality within limits over time","Remain unchanged under every condition forever","Avoid all packaging","Increase potency during storage"],"correctIndex":0,"explanation":"Stability means the product remains within specified quality limits during its shelf life under stated conditions.","explanationNe":"निर्धारित भण्डारण अवस्थामा shelf life भरि उत्पादन तोकिएको गुणस्तर सीमाभित्र रहनु stability हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mcq-40','Pharmacy','Diploma in Pharmacy','mcq','free',1640,'{"question":"A beyond-use date is especially relevant to:","translation":"Beyond-use date विशेषगरी कुन अवस्थामा महत्त्वपूर्ण हुन्छ?","options":["Compounded or repackaged preparations as assigned under applicable standards","The original manufacturer''s expiry in every case","The date a prescription is written","The date a patient visits"],"correctIndex":0,"explanation":"A beyond-use date is assigned to a prepared or repackaged product according to applicable standards and evidence.","explanationNe":"तयार वा पुनः प्याक गरिएको औषधिलाई लागू मापदण्ड र प्रमाणका आधारमा beyond-use date दिइन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-01','Pharmacy','Diploma in Pharmacy','mock','free',1701,'{"question":"Define pharmaceutics and state its importance.","answer":"Pharmaceutics is the science of designing, preparing and evaluating dosage forms. It ensures medicines are delivered safely, accurately, stably and acceptably.","answerNe":"Pharmaceutics औषधिको dosage form डिजाइन, तयारी र मूल्याङ्कन गर्ने विज्ञान हो। यसले औषधि सुरक्षित, सही मात्रा, स्थिर र स्वीकार्य रूपमा दिन मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-02','Pharmacy','Diploma in Pharmacy','mock','free',1702,'{"question":"Classify common pharmaceutical dosage forms with examples.","answer":"Dosage forms include solids (tablets, capsules, powders), liquids (solutions, syrups, suspensions, emulsions), semisolids (ointments, creams, gels) and special forms (suppositories, injections, inhalations).","answerNe":"Dosage form मा ठोस (tablet, capsule, powder), तरल (solution, syrup, suspension, emulsion), अर्धठोस (ointment, cream, gel) र विशेष तयारी (suppository, injection, inhalation) पर्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-03','Pharmacy','Diploma in Pharmacy','mock','free',1703,'{"question":"Differentiate a solution, suspension and emulsion.","answer":"A solution is a homogeneous mixture. A suspension has insoluble solid particles dispersed in liquid. An emulsion has droplets of one immiscible liquid dispersed in another.","answerNe":"Solution समान मिश्रण हो। Suspension मा नघुल्ने ठोस कण तरलमा फैलिन्छन्। Emulsion मा नमिसिने एउटा तरलका थोपा अर्को तरलमा फैलिन्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-04','Pharmacy','Diploma in Pharmacy','mock','free',1704,'{"question":"Explain the functions of common tablet excipients.","answer":"Diluents add bulk, binders provide cohesion, disintegrants help tablet breakup, lubricants reduce friction and glidants improve powder flow. Excipients must be suitable and compatible.","answerNe":"Diluent ले आकार बढाउँछ, binder ले कण बाँध्छ, disintegrant ले tablet टुक्र्याउँछ, lubricant ले घर्षण घटाउँछ र glidant ले powder flow सुधार्छ। Excipient उपयुक्त र compatible हुनुपर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-05','Pharmacy','Diploma in Pharmacy','mock','free',1705,'{"question":"Describe the main steps in conventional tablet manufacture.","answer":"Typical steps may include weighing, sieving, mixing, granulation when required, drying, sizing, lubrication, compression and suitable packaging. The exact process depends on the formulation.","answerNe":"सामान्य चरणमा तौल, चाल्ने, मिसाउने, आवश्यक भए granulation, सुकाउने, sizing, lubrication, compression र उपयुक्त packaging पर्छन्। वास्तविक प्रक्रिया formulation अनुसार फरक हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-06','Pharmacy','Diploma in Pharmacy','mock','free',1706,'{"question":"What is enteric coating? State its purpose.","answer":"Enteric coating resists gastric fluid and dissolves under suitable intestinal conditions. It may protect acid-sensitive drugs or reduce gastric exposure to an irritating drug.","answerNe":"Enteric coating पेटको तरलमा नघुली आन्द्राको उपयुक्त अवस्थामा घुल्छ। यसले acid-sensitive औषधि जोगाउन वा पेटको सम्पर्क घटाउन सक्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-07','Pharmacy','Diploma in Pharmacy','mock','free',1707,'{"question":"Explain the difference between sterilization and disinfection.","answer":"Sterilization destroys or removes all forms of microbial life, including bacterial spores, when properly validated. Disinfection reduces or destroys many pathogenic microorganisms but may not eliminate spores.","answerNe":"Sterilization ले सही validation हुँदा bacterial spore सहित सबै प्रकारका सूक्ष्मजीव हटाउँछ वा नष्ट गर्छ। Disinfection ले धेरै रोगकारक सूक्ष्मजीव घटाउँछ वा नष्ट गर्छ तर spore सबै हटाउन नहुन सक्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-08','Pharmacy','Diploma in Pharmacy','mock','free',1708,'{"question":"What is bioavailability? Mention factors that can affect it.","answer":"Bioavailability is the rate and extent of active drug reaching systemic circulation. It may be affected by dosage form, dissolution, absorption, food, metabolism and route of administration.","answerNe":"Systemic circulation मा सक्रिय औषधि पुग्ने गति र परिमाण bioavailability हो। Dosage form, dissolution, absorption, खाना, metabolism र administration route ले असर गर्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-09','Pharmacy','Diploma in Pharmacy','mock','free',1709,'{"question":"Explain the importance of pharmacopoeial standards.","answer":"Pharmacopoeial standards specify identity, strength, purity, quality tests and accepted methods for listed substances or preparations. They support consistent quality and regulatory control.","answerNe":"Pharmacopoeia ले पहिचान, शक्ति, शुद्धता, गुणस्तर परीक्षण र विधि तोक्छ। यसले समान गुणस्तर र नियामक नियन्त्रणमा सहयोग गर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-10','Pharmacy','Diploma in Pharmacy','mock','free',1710,'{"question":"Differentiate a pharmacopoeia and a formulary.","answer":"A pharmacopoeia is an official compendium of quality standards and test methods. A formulary is a selected list of medicines with practical information on their use.","answerNe":"Pharmacopoeia औषधिको गुणस्तर मापदण्ड र परीक्षण विधिको आधिकारिक संग्रह हो। Formulary औषधिको छनोट सूची र प्रयोगसम्बन्धी जानकारी हो।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-11','Pharmacy','Diploma in Pharmacy','mock','free',1711,'{"question":"Define percentage strength and explain % w/v with an example.","answer":"Percentage w/v expresses grams of solute in 100 mL of final solution. A 2% w/v solution contains 2 g solute made up to 100 mL.","answerNe":"प्रतिशत w/v ले अन्तिम १०० mL solution मा solute का ग्राम जनाउँछ। २% w/v मा २ ग्राम solute राखी अन्तिम आयतन १०० mL बनाइन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-12','Pharmacy','Diploma in Pharmacy','mock','free',1712,'{"question":"A preparation requires 5 g of solute in 100 mL. Express its strength as % w/v.","answer":"It is 5% w/v because it contains 5 g in each 100 mL of final preparation.","answerNe":"प्रत्येक १०० mL मा ५ ग्राम भएकाले यसको शक्ति ५% w/v हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-13','Pharmacy','Diploma in Pharmacy','mock','free',1713,'{"question":"Explain the dilution equation C1V1 = C2V2 and its use.","answer":"The equation is used for simple dilution when the amount of solute is conserved. C1 and V1 are initial concentration and volume; C2 and V2 are final concentration and volume.","answerNe":"Solute को मात्रा उही रहने साधारण dilution मा यो सूत्र प्रयोग हुन्छ। C1 र V1 सुरुको concentration र volume हुन्; C2 र V2 अन्तिम concentration र volume हुन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-14','Pharmacy','Diploma in Pharmacy','mock','free',1714,'{"question":"Describe the correct use of a measuring cylinder.","answer":"Use a clean suitable cylinder on a level surface. Allow the liquid to settle and read the meniscus at eye level; for many aqueous liquids read the bottom of the meniscus.","answerNe":"सफा र उपयुक्त cylinder समथर सतहमा राख्नुहोस्। तरल स्थिर भएपछि आँखाको तहमा meniscus पढ्नुहोस्; धेरै जलीय तरलमा तल्लो भाग पढिन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-15','Pharmacy','Diploma in Pharmacy','mock','free',1715,'{"question":"What is a buffer solution and why may it be used in formulations?","answer":"A buffer resists pH change after small additions of acid or base. It may help maintain drug stability, solubility or product performance when appropriate.","answerNe":"Buffer ले थोरै acid वा base थप्दा pH परिवर्तन कम गर्छ। उपयुक्त अवस्थामा यसले औषधिको stability, solubility वा कार्यसम्पादन कायम राख्न सक्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-16','Pharmacy','Diploma in Pharmacy','mock','free',1716,'{"question":"Explain the role of preservatives in pharmaceutical preparations.","answer":"Preservatives inhibit microbial growth in suitable preparations, particularly some multi-dose products. They do not replace hygienic manufacture, correct storage or sterility requirements where applicable.","answerNe":"Preservative ले उपयुक्त तयारी, विशेषगरी केही multi-dose उत्पादनमा सूक्ष्मजीव वृद्धि रोक्छ। यसले स्वच्छ निर्माण, सही भण्डारण वा आवश्यक sterility को विकल्प लिँदैन।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-17','Pharmacy','Diploma in Pharmacy','mock','free',1717,'{"question":"List important quality considerations for a pharmaceutical suspension.","answer":"Consider particle size, sedimentation rate, ease of redispersion, viscosity, physical stability, microbial quality where applicable and dose uniformity.","answerNe":"Particle size, sedimentation rate, सजिलै फेरि मिसिने क्षमता, viscosity, भौतिक स्थिरता, आवश्यक microbial quality र dose uniformity जाँच्नुपर्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-18','Pharmacy','Diploma in Pharmacy','mock','free',1718,'{"question":"Explain the difference between FIFO and FEFO in pharmaceutical storage.","answer":"FIFO means first-in, first-out by receipt date. FEFO means first-expiry, first-out by expiry date and is generally preferred when batches have different expiry dates.","answerNe":"FIFO मा पहिले आएको सामान पहिले निकालिन्छ। FEFO मा पहिले म्याद सकिने सामान पहिले निकालिन्छ र म्याद फरक भएका ब्याचमा सामान्यतया FEFO प्राथमिक हुन्छ।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-19','Pharmacy','Diploma in Pharmacy','mock','free',1719,'{"question":"What is pharmaceutical stability? Mention common factors affecting it.","answer":"Stability is the ability to remain within specified quality limits throughout shelf life. Temperature, humidity, light, oxygen, pH, packaging and formulation can affect it.","answerNe":"Shelf life भरि तोकिएको गुणस्तर सीमाभित्र रहने क्षमता stability हो। तापक्रम, चिस्यान, प्रकाश, अक्सिजन, pH, packaging र formulation ले असर गर्छन्।"}'::jsonb,true),
('dph-pharmaceutics-extra-mock-20','Pharmacy','Diploma in Pharmacy','mock','free',1720,'{"question":"Differentiate expiry date and beyond-use date.","answer":"Expiry date is assigned by the manufacturer based on approved stability data for the marketed product. Beyond-use date is assigned to a compounded or repackaged preparation under applicable standards and evidence.","answerNe":"Expiry date बजारमा आउने उत्पादनका लागि निर्माताले stability data का आधारमा तोक्छ। Beyond-use date तयार वा पुनः प्याक गरिएको तयारीलाई लागू मापदण्ड र प्रमाणअनुसार दिइन्छ।"}'::jsonb,true)
